WITH valid AS (SELECT *, ROUND(duration_sec, 1) AS duration_sec_rounded, CASE WHEN page = '/checkout' THEN 1 ELSE 0 END AS is_checkout, COALESCE(page, 'UNKNOWN') AS page_clean FROM web_events WHERE session_id IN (16, 37)), base AS (SELECT id, session_id, duration_sec, duration_sec_rounded, CAST(duration_sec_rounded AS INT) AS duration_sec_rounded_int, CAST(duration_sec AS STRING) AS duration_sec_num, COALESCE(page, 'OTHER') AS page_filled FROM valid WHERE page IS NOT NULL AND event_time > TIMESTAMP '2023-05-16 22:00:00'), with_windows AS (SELECT id, session_id, duration_sec, duration_sec_num, page_filled, SUM(duration_sec_rounded) OVER (PARTITION BY session_id ORDER BY duration_sec_rounded, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_duration_sec_rounded, AVG(duration_sec_rounded) OVER (PARTITION BY session_id ORDER BY duration_sec_rounded, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_duration_sec_rounded, MAX(duration_sec_rounded) OVER (PARTITION BY session_id ORDER BY duration_sec_rounded, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_duration_sec_rounded, SUM(duration_sec_rounded) OVER (PARTITION BY session_id ORDER BY duration_sec_rounded, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_duration_sec_rounded FROM base), scored AS (SELECT *, SUM(running_duration_sec_rounded) OVER (PARTITION BY session_id ORDER BY running_sum_duration_sec_rounded, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_sum_running_duration_sec_rounded, AVG(running_duration_sec_rounded) OVER (PARTITION BY session_id ORDER BY running_sum_duration_sec_rounded, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_avg_running_duration_sec_rounded, MIN(running_duration_sec_rounded) OVER (PARTITION BY session_id ORDER BY running_sum_duration_sec_rounded, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_min_running_duration_sec_rounded, COUNT(running_duration_sec_rounded) OVER (PARTITION BY session_id ORDER BY running_sum_duration_sec_rounded, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_count_running_duration_sec_rounded, NTILE(4) OVER (PARTITION BY session_id ORDER BY running_duration_sec_rounded, id) AS running_duration_sec_rounded_bucket FROM with_windows WHERE running_avg_duration_sec_rounded >= 68) SELECT id, session_id, duration_sec_num, running_sum_duration_sec_rounded, running_avg_duration_sec_rounded, running_max_duration_sec_rounded, running_duration_sec_rounded, last3_min_running_duration_sec_rounded, running_duration_sec_rounded_bucket FROM scored
